import type {CanonicalPropertyNode,CanonicalRule} from "./data-layer-canonical-schema.js";
import {focusedRuleFields} from "./data-layer-focused-schema-property-ui.js";

export interface CanonicalFocusedRuleRowsContext {dom:Document;getWorking:()=>CanonicalPropertyNode|undefined;removedRuleIds:Set<string>;invariant:boolean;id:(kind:string)=>string;render:()=>void;feedback:(message:string)=>void;}
const clone=<T>(value:T):T=>structuredClone(value);
const labeled=(dom:Document,text:string,control:HTMLElement):HTMLLabelElement=>{const label=dom.createElement("label");label.append(text,control);return label;};
const input=(dom:Document,name:string,value="",type="text"):HTMLInputElement=>{const control=dom.createElement("input");control.name=name;control.type=type;control.value=value;return control;};
const button=(dom:Document,text:string,run:()=>void):HTMLButtonElement=>{const control=dom.createElement("button");control.type="button";control.textContent=text;control.addEventListener("click",run);return control;};
const ruleKindLabel=(rule:CanonicalRule):string=>rule.name??rule.kind;

function editRule(row:HTMLElement,rule:CanonicalRule,context:CanonicalFocusedRuleRowsContext):void {
  const {dom}=context,editor=dom.createElement("fieldset"),legend=dom.createElement("legend");legend.textContent=`Edit ${ruleKindLabel(rule)}`;
  for(const field of focusedRuleFields(rule.kind)){if(field==="condition"){const tree=dom.createElement("div");tree.setAttribute("aria-label","Shared rule condition tree");const render=(condition:CanonicalRule["condition"],path:string):void=>{if(!condition)return;const item=dom.createElement("article");item.dataset.conditionId=condition.id??`rule-condition:${rule.id}:${path}`;item.textContent=condition.kind==="predicate"?`${condition.propertyId} ${condition.operator}${condition.value===undefined?"":` ${String(condition.value)}`}`:`${condition.kind} (${condition.children.length})`;tree.append(item);if(condition.kind!=="predicate")condition.children.forEach((child,index)=>render(child,`${path}.${index}`));};render(rule.condition,"root");editor.append(labeled(dom,"Condition tree",tree));continue;}const value=String((rule as any)[field]??""),control=input(dom,`editRule${field[0]!.toUpperCase()+field.slice(1)}`,value,["minimum","maximum","minItems","maxItems"].includes(field)?"number":"text");control.addEventListener("input",()=>{const working=context.getWorking();if(!working)return;const index=working.rules.findIndex(({id})=>id===rule.id);if(index<0)return;const next=clone(working.rules[index]!);(next as any)[field]=control.value===""?undefined:["minimum","maximum","minItems","maxItems"].includes(field)?Number(control.value):control.value;working.rules[index]=next;});editor.append(labeled(dom,field,control));}
  row.append(editor);
}

export function renderCanonicalRuleRows(host:HTMLElement,context:CanonicalFocusedRuleRowsContext):void {
  const {dom,removedRuleIds,invariant}=context,working=context.getWorking();if(!working)return;const list=dom.createElement("div");list.setAttribute("aria-label","Stable rule inventory");
  for(const rule of working.rules){const row=dom.createElement("article"),summary=dom.createElement("p"),inherited=rule.provenance?.state==="inherited"||rule.provenance?.state==="shadowed",removed=removedRuleIds.has(rule.id);row.dataset.ruleId=rule.id;row.dataset.ownership=inherited?"inherited":"local";summary.textContent=`${ruleKindLabel(rule)} · ${rule.kind} · ${rule.severity} · ${rule.message??"No issue message"} · source ${rule.provenance?.contributorName??"local"}${removed?" · Removed":""}`;row.append(summary,button(dom,"View",()=>{row.dataset.ruleMode="view";const detail=dom.createElement("p");detail.textContent=`Rule ${rule.id} · definition ${JSON.stringify(rule)} · effective ${rule.enabled===false?"disabled":"enabled"} · source ${rule.provenance?.contributorName??"local"}`;row.append(detail);}));
    if(inherited){row.append(...(invariant?[]:[button(dom,"Replace here",()=>replaceInheritedRule(rule,context))]),button(dom,"Open source",()=>{row.dataset.ruleMode="source";const source=dom.createElement("p");source.textContent=`Source rule ${rule.id} · ${ruleKindLabel(rule)} · inherited definition is read-only.`;row.append(source);}));}
    else if(removed){const impact=dom.createElement("p");impact.textContent=`Impact review: ${ruleKindLabel(rule)} · effective result falls back to parent or unset.`;row.append(impact,button(dom,"Restore",()=>{removedRuleIds.delete(rule.id);context.render();}));}
    else row.append(button(dom,"Edit",()=>{row.dataset.ruleMode="edit";editRule(row,rule,context);}),button(dom,"Remove local",()=>{removedRuleIds.add(rule.id);context.feedback(`Staged removal of ${ruleKindLabel(rule)}.`);context.render();}));
    list.append(row);
  }
  host.append(list);
}

function replaceInheritedRule(rule:CanonicalRule,context:CanonicalFocusedRuleRowsContext):void {const next=context.getWorking();if(!next)return;const index=next.rules.findIndex(({id})=>id===rule.id);if(index<0)return;const replacement=clone(next.rules[index]!);replacement.id=context.id("rule");replacement.provenance={source:"created",state:"effective"};next.rules[index]=replacement;context.feedback(`Staged replacement of ${ruleKindLabel(rule)}.`);context.render();}
